// Webhook entry: same checks as the FastAPI /ask endpoint; adds a sessionId for agent memory.
const body = $input.first().json.body || {};
const question = typeof body.question === 'string' ? body.question : '';
const maxChars = 10000;
let error = null;
if (!question.trim()) error = 'question must not be blank';
else if (question.length > maxChars) error = 'question exceeds MAX_QUESTION_CHARS';
return [{
  json: {
    valid: error === null,
    error,
    chatInput: question,
    sessionId: typeof body.sessionId === 'string' && body.sessionId ? body.sessionId : `api-${$execution.id}`,
  },
}];

// Shape the agent's output like the original API ({answer, route, sources}) and keep `output` for chat.
const item = $input.first().json;
const steps = Array.isArray(item.intermediateSteps) ? item.intermediateSteps : [];

function parseObservation(obs) {
  let value = obs;
  for (let i = 0; i < 2 && typeof value === 'string'; i++) {
    try { value = JSON.parse(value); } catch (e) { break; }
  }
  if (Array.isArray(value)) return value.flatMap((v) => parseObservation(v));
  if (value && typeof value === 'object') {
    if (value.json && typeof value.json === 'object') return parseObservation(value.json);
    if (typeof value.response === 'string' || typeof value.text === 'string') return parseObservation(value.response ?? value.text);
    return [value];
  }
  return [];
}

const sources = [];
const seen = new Set();
const routes = [];
const toolsUsed = [];
for (const step of steps) {
  if (step.action?.tool) toolsUsed.push(step.action.tool);
  for (const res of parseObservation(step.observation)) {
    if (res.route && res.route !== 'error') routes.push(res.route);
    for (const s of res.sources || []) {
      const key = `${s.name}\u0000${s.link}`;
      if (s.link && !seen.has(key)) { seen.add(key); sources.push({ name: s.name, link: s.link }); }
    }
  }
}

const answer = String(item.output ?? '');
return [{
  json: {
    answer,
    route: routes.length ? routes[routes.length - 1] : 'llm_only',
    sources,
    tools_used: toolsUsed,
    output: answer,
  },
}];

// Entry point for every agent tool call: work out what to run and in which "route".
const cfg = $('Config').first().json;
const call = $('Tool Call Trigger').first().json;

const CONTRACT_COLUMNS = [
  'Project_ID__c', 'TM_TOMA__Exercised_Contract_Value__c', 'Business_Area__c',
  'Closeout_Time_Standard__c', 'Finance_Analyst__r.Name', 'ContractAdministrator__r.Name',
  'Contract_Administrator_Email_Id__c', 'Contract_Manager__r.Name', 'Contracting_Officer__r.Name',
  'Contracting_Officer_Email__c', 'Contracts_Director__r.Name', 'Technical_Director__r.Name',
  'Operations_Director__r.Name', 'Program_Area_Lead__r.Name', 'Program_Manager__r.Name',
  'Program_Manager_Email_Id__c', 'Subcontract_Admin__r.Name', 'Subcontract_Manager__c',
  'Contract_Name', 'TM_TOMA__Contract_Type__c', 'name', 'link', 'lastModifiedDateTime',
  'drive_id', 'Project', 'Project_x003a_PCN', 'Contracts_x0020_Subfolder',
];
const OPPORTUNITY_COLUMNS = [
  'Id', 'LastModifiedDate', 'Name', 'Description', 'Capabilities__c', 'Capability_Areas__c',
  'Sub_Capability__c', 'Project_Name__c', 'Business_Area__c', 'StageName', 'Status__c',
  'Proposal_Status__c', 'Amount', 'Pipeline_Total__c', 'Award_Date_Formula__c',
  'FedCapture__Our_Role__c',
];

const tool = String(call.tool || '');
const question = String(call.query || '');
let planRaw = call.plan;
if (planRaw && typeof planRaw === 'object') planRaw = JSON.stringify(planRaw);
planRaw = String(planRaw ?? '').trim();
const hasPlan = planRaw !== '' && planRaw !== '{}' && planRaw.toLowerCase() !== 'null' && planRaw.toLowerCase() !== 'none';

const entity = tool === 'opportunities' ? 'opportunities' : 'contract_metadata';
const lower = question.toLowerCase();
const recent = question.match(/\b(?:last|past)\s+(\d+)\s+years?\b/i);
const baseOnly = lower.includes('base contract');

let route;
let needsSql;
if (tool === 'contracts' || tool === 'opportunities') { route = 'sql_only'; needsSql = true; }
else if (tool === 'contract_docs' && hasPlan) { route = baseOnly ? 'sql_and_docs_base' : 'sql_and_docs_all'; needsSql = true; }
else if (tool === 'contract_docs') { route = 'docs_only'; needsSql = false; }
else if (tool === 'reference_docs') { route = 'reference_docs'; needsSql = false; }
else throw new Error(`Unknown tool: ${tool}`);

if (route === 'sql_only' && !hasPlan) {
  throw new Error('A JSON query plan is required for this tool.');
}

return [{
  json: {
    tool,
    question,
    planRaw: hasPlan ? planRaw : '{}',
    route,
    needsSql,
    entity,
    baseOnly,
    recentYears: recent ? parseInt(recent[1], 10) : null,
    allowedColumns: [...(entity === 'opportunities' ? OPPORTUNITY_COLUMNS : CONTRACT_COLUMNS)].sort(),
    table: entity === 'opportunities' ? cfg.postgresOpportunitiesTable : cfg.postgresContractsTable,
  },
}];

// Port of QueryPlanner validation + Workflow.query_contracts overrides + PostgresRepository._build_query.
// Only whitelisted, quoted identifiers reach the SQL text; every value is a bound parameter.
const cfg = $('Config').first().json;
const ctx = $('Parse Tool Call').first().json;
const allowed = new Set(ctx.allowedColumns);
const fail = (msg) => { throw new Error(msg); };

let raw;
try {
  const content = String(ctx.planRaw);
  const match = content.replace(/```(?:json)?/gi, '').match(/\{[\s\S]*\}/);
  raw = JSON.parse(match ? match[0] : content);
} catch (e) {
  fail('The plan is not a valid JSON query plan');
}
if (!raw || typeof raw !== 'object' || Array.isArray(raw)) {
  fail('The plan is not a valid JSON query plan');
}

const plan = {
  entity: raw.entity,
  columns: Array.isArray(raw.columns) ? raw.columns : [],
  filters: raw.filters && typeof raw.filters === 'object' && !Array.isArray(raw.filters) ? raw.filters : {},
  limit: Number.isInteger(raw.limit) && raw.limit > 0 ? raw.limit : 100,
  order_by: raw.order_by ?? null,
  descending: raw.descending === true,
  distinct: raw.distinct === true,
  active_only: raw.active_only === true,
  base_contract_only: raw.base_contract_only === true,
  modified_within_years: Number.isInteger(raw.modified_within_years) && raw.modified_within_years > 0
    ? raw.modified_within_years : null,
};

if (plan.entity !== ctx.entity) fail('The plan has the wrong entity for this tool');
if (!plan.columns.every((c) => allowed.has(c))) fail('The plan uses columns that are not allowed');
if (!Object.keys(plan.filters).every((c) => allowed.has(c))) fail('The plan filters on columns that are not allowed');
if (plan.order_by !== null && !allowed.has(plan.order_by)) fail('The plan orders by a column that is not allowed');
for (const v of Object.values(plan.filters)) {
  if (!['string', 'number', 'boolean'].includes(typeof v)) fail('The plan is not a valid JSON query plan');
}

// Workflow.query_contracts adjustments for the "SQL then documents" routes.
const docsRoute = ctx.route === 'sql_and_docs_all' || ctx.route === 'sql_and_docs_base';
if (docsRoute) {
  plan.base_contract_only = ctx.baseOnly || plan.base_contract_only;
  if (plan.modified_within_years === null && ctx.recentYears) plan.modified_within_years = ctx.recentYears;
  plan.columns = ['drive_id', 'link', 'name'];
  if (plan.distinct && plan.order_by && !plan.columns.includes(plan.order_by)) plan.columns.push(plan.order_by);
}

const IDENT = /^[A-Za-z_][A-Za-z0-9_.]*$/;
const q = (id) => {
  if (!IDENT.test(id)) fail(`Invalid configured SQL identifier: ${id}`);
  return `"${id}"`;
};

let requested = plan.columns.length ? [...plan.columns] : [...ctx.allowedColumns];
if (plan.distinct && plan.order_by && !requested.includes(plan.order_by)) requested.push(plan.order_by);

const params = [];
const clauses = [];
const isContracts = plan.entity === 'contract_metadata';
for (const [column, value] of Object.entries(plan.filters)) {
  // Salesforce metadata fields are stored as text, including numeric-looking project IDs.
  params.push(isContracts ? String(value) : value);
  clauses.push(`${q(column)} = $${params.length}`);
}
if (isContracts && plan.active_only) clauses.push('"Closeout_Time_Standard__c"::date > CURRENT_DATE');
if (isContracts && plan.base_contract_only) {
  params.push('Base Contract');
  clauses.push(`"Contracts_x0020_Subfolder" = $${params.length}`);
}
if (isContracts && plan.modified_within_years !== null) {
  params.push(plan.modified_within_years);
  clauses.push(`"lastModifiedDateTime"::timestamptz >= CURRENT_DATE - ($${params.length} * INTERVAL '1 year')`);
}

const where = clauses.length ? ` WHERE ${clauses.join(' AND ')}` : '';
const order = plan.order_by ? ` ORDER BY ${q(plan.order_by)} ${plan.descending ? 'DESC' : 'ASC'}` : '';
params.push(Math.min(plan.limit, Number(cfg.maxSqlRows)));
const inner = `SELECT ${plan.distinct ? 'DISTINCT ' : ''}${requested.map(q).join(', ')} ` +
  `FROM ${q(cfg.postgresSchema)}.${q(ctx.table)}${where}${order} LIMIT $${params.length}`;
// Wrap so Postgres always returns exactly one row ({records: [...]}), even when nothing matches.
const sql = `SELECT COALESCE(json_agg(t), '[]'::json) AS records FROM (${inner}) AS t`;

return [{ json: { sql, params, plan } }];

// Unpack the json_agg result and decide whether documents are needed next.
const ctx = $('Parse Tool Call').first().json;
let records = $input.first().json.records ?? [];
if (typeof records === 'string') records = JSON.parse(records);

return [{
  json: {
    question: ctx.question,
    route: ctx.route,
    needsDocs: ctx.route !== 'sql_only',
    records,
  },
}];

// Tool result for query_contracts / query_opportunities: rows without drive_id, plus sources.
const { route, records } = $input.first().json;
const visible = records.map((r) => Object.fromEntries(
  Object.entries(r).filter(([k, v]) => k !== 'drive_id' && v !== null && v !== undefined),
));
const seen = new Set();
const sources = [];
for (const r of records) {
  if (typeof r.link !== 'string' || !r.link) continue;
  const name = String(r.name || r.Contract_Name || r.link);
  const key = `${name}\u0000${r.link}`;
  if (!seen.has(key)) { seen.add(key); sources.push({ name, link: r.link }); }
}
return [{
  json: {
    route,
    result: records.length
      ? `${records.length} matching record(s). Answer only from these rows.`
      : 'No matching records were found.',
    records: visible,
    sources,
  },
}];

// Port of ChromaClient.search_contracts / search_reference request setup.
const cfg = $('Config').first().json;
const ctx = $('Parse Tool Call').first().json;
const route = ctx.route;

let fileIds = [];
if (route === 'sql_and_docs_all' || route === 'sql_and_docs_base') {
  fileIds = ($input.first().json.records || [])
    .filter((r) => r.drive_id)
    .map((r) => String(r.drive_id));
}

const filtered = fileIds.length > 0;
const limitedIds = fileIds.slice(0, Number(cfg.maxFileIds));
const collection = route === 'reference_docs' ? cfg.chromaReferenceCollection : cfg.chromaContractCollection;

return [{
  json: {
    question: ctx.question,
    route,
    collection,
    filtered,
    // Filtered searches only need top-K; broad searches pull a large candidate pool for BM25 re-ranking.
    nResults: Number(filtered ? cfg.chromaTopK : cfg.chromaCandidateK),
    where: filtered ? { drive_id: { $in: limitedIds } } : null,
    embeddingModel: cfg.embeddingModel || '',
  },
}];

// Port of chroma/search.py (normalize_results, hybrid_rank_results) + Workflow._grounded_answer.
const cfg = $('Config').first().json;
const search = $('Prepare Chroma Search').first().json;
// The Chroma Vector Store node emits one item per hit ({document, score}); score is Chroma's distance.
const hits = $input.all().map((i) => i.json).filter((j) => j && j.document);
const results = {
  documents: [hits.map((h) => h.document.pageContent)],
  metadatas: [hits.map((h) => h.document.metadata || {})],
  distances: [hits.map((h) => h.score)],
};
const topK = Number(cfg.chromaTopK);

const documents = (results.documents && results.documents[0]) || [];
const metadatas = (results.metadatas && results.metadatas[0]) || [];
const distances = (results.distances && results.distances[0]) || [];
const isNum = (v) => typeof v === 'number' && Number.isFinite(v);
const metaAt = (i) => (i < metadatas.length && metadatas[i]) ? metadatas[i] : {};

function normalizeResults() {
  return documents.map((doc, i) => {
    const m = metaAt(i);
    const d = i < distances.length ? distances[i] : null;
    return { content: String(doc), name: m.name || m.source || null, link: m.link || null, score: isNum(d) ? 1 - d : null };
  });
}

function hybridRankResults(query, limit) {
  const tokenize = (t) => t.match(/[a-z0-9]{3,}/g) || [];
  const BM25_K1 = 1.5;
  const BM25_B = 0.75;
  const queryTerms = [...new Set(tokenize(query.toLowerCase()))];
  const numeric = distances.filter(isNum);
  const best = numeric.length ? Math.min(...numeric) : 0;
  const worst = numeric.length ? Math.max(...numeric) : best;
  const span = worst - best;
  const n = Math.min(documents.length, metadatas.length);
  const tokenized = [];
  for (let i = 0; i < n; i++) tokenized.push(tokenize(`${(metadatas[i] || {}).name || ''} ${documents[i]}`.toLowerCase()));
  const avgLen = documents.length && tokenized.length ? tokenized.reduce((s, t) => s + t.length, 0) / tokenized.length : 0;
  const df = {};
  for (const term of queryTerms) df[term] = tokenized.filter((t) => t.includes(term)).length;
  const bm25 = tokenized.map((tokens) => {
    let score = 0;
    for (const term of queryTerms) {
      const tf = tokens.filter((t) => t === term).length;
      if (!tf) continue;
      // Same IDF form as the Python implementation (uses the chunk's token count).
      const idf = Math.log(1 + ((tokens.length - df[term] + 0.5) / (df[term] + 0.5)));
      const denom = tf + BM25_K1 * (1 - BM25_B + BM25_B * (tokens.length / avgLen));
      score += idf * (tf * (BM25_K1 + 1) / denom);
    }
    return score;
  });
  const maxBm25 = bm25.length ? Math.max(...bm25) : 0;
  const chunks = documents.map((doc, i) => {
    const m = metaAt(i);
    const d = i < distances.length ? distances[i] : null;
    const semantic = isNum(d) && span ? 1 - ((d - best) / span) : 1.0;
    const b = i < bm25.length ? bm25[i] : 0;
    const keyword = maxBm25 ? b / maxBm25 : 0;
    return {
      content: String(doc), name: m.name || m.source || null, link: m.link || null,
      score: semantic, bm25_score: b, keyword_score: keyword, hybrid_score: (semantic + keyword) / 2,
    };
  });
  return chunks.sort((a, b) => b.hybrid_score - a.hybrid_score).slice(0, limit);
}

const chunks = search.filtered ? normalizeResults() : hybridRankResults(search.question, topK);

// _grounded_answer: one chunk per (name, link), sources with links only.
const unique = [];
const seen = new Set();
for (const c of chunks) {
  const key = `${c.name || ''}\u0000${c.link || ''}`;
  if (!seen.has(key)) { seen.add(key); unique.push(c); }
}
const sources = [];
const seenSrc = new Set();
for (const c of unique) {
  if (typeof c.link !== 'string' || !c.link) continue;
  const name = String(c.name || c.link);
  const key = `${name}\u0000${c.link}`;
  if (!seenSrc.has(key)) { seenSrc.add(key); sources.push({ name, link: c.link }); }
}

const route = search.route;
if (!unique.length) {
  const message = route === 'reference_docs'
    ? "The provided context doesn't cover this."
    : 'No relevant document content was found.';
  return [{ json: { route, result: message, sources } }];
}

const contentLimit = Math.max(400, Math.floor(Number(cfg.maxRagContextChars) / unique.length));
const context = unique.map((c) =>
  `Source: ${c.name || 'document'}\nLink: ${c.link || ''}\nContent: ${String(c.content).slice(0, contentLimit)}`,
).join('\n\n');
return [{ json: { route, result: `Document excerpts (answer only from these):\n\n${context}`, sources } }];

// Any failure inside a tool comes back to the agent as text so it can fix its input or explain.
const item = $input.first().json;
const msg = [item.error?.message, item.error, item.message]
  .find((v) => typeof v === 'string' && v) ?? JSON.stringify(item.error ?? item).slice(0, 300);
const clean = msg.replace(/ \[line \d+\]$/, '');
let hint = '';
try {
  const ctx = $('Parse Tool Call').first(0).json; // branch 0 = its success output
  if (/planner|plan|column|filter|entity|JSON/i.test(clean)) {
    hint = ` Allowed columns: ${JSON.stringify(ctx.allowedColumns)}. Fix the plan and call the tool again.`;
  }
} catch (e) {
  // Parse Tool Call itself failed; no column hint available.
}
return [{ json: { route: 'error', result: `ERROR: ${clean}.${hint}`, sources: [] } }];
